function c=compact_ac_build(m,anchor_ids)
%COMPACT_AC_BUILD Exact complex-admittance reduction of passive zero-injection nodes.
% The output is a matrix network, not a MATPOWER physical-branch case.
% Fixed shunts, line charging and complex taps remain in Y. Currents refer to
% the original branches through recovery operators, never fictitious edges.
root=fileparts(fileparts(fileparts(fileparts(mfilename('fullpath')))));
if nargin<2||isempty(anchor_ids)
    registry=readtable(fullfile(root,'output','nygrid_2025_slim','network','bus_register.csv'));
    anchor_ids=double(registry.model_bus(:));assert(numel(anchor_ids)==148);
end
ids=double(m.bus(:,1));anchor_ids=double(anchor_ids(:));nb=numel(ids);nl=size(m.branch,1);
assert(numel(unique(ids))==nb&&numel(unique(anchor_ids))==numel(anchor_ids),'compactAC:DuplicateBus','Bus IDs must be unique.');
assert(all(ismember(anchor_ids,ids)),'compactAC:MissingAnchor','A requested retained bus is absent from the detailed case.');
assert(all(m.bus(:,2)~=4),'compactAC:OfflineBus','Remove explicit NONE buses before constructing this matrix model.');
assert(all(isfinite(m.bus),'all')&&all(isfinite(m.branch(:,1:13)),'all'));
is_anchor=ismember(ids,anchor_ids);
load_port=m.bus(:,3)~=0|m.bus(:,4)~=0;
generator_port=ismember(ids,m.gen(:,1));
dc_port=false(nb,1);
if isfield(m,'dcline')&&~isempty(m.dcline),dc_port=ismember(ids,reshape(m.dcline(:,1:2),[],1));end
control_port=ismember(m.bus(:,2),[2 3]);
required=load_port|generator_port|dc_port|control_port;
extra_ids=ids(required&~is_anchor);
retained_ids=[anchor_ids;extra_ids];
[ok,k]=ismember(retained_ids,ids);assert(all(ok));
e=find(~ismember(ids,retained_ids));nk=numel(k);
assert(all(m.bus(e,3:4)==0,'all')&&~any(generator_port(e)|dc_port(e)|control_port(e)), ...
    'compactAC:NonPassiveElimination','An eliminated node has a prescribed injection or voltage control.');
bus_i=m.bus;bus_i(:,1)=(1:nb)';branch_i=m.branch;
[ok,f]=ismember(m.branch(:,1),ids);assert(all(ok));[ok,t]=ismember(m.branch(:,2),ids);assert(all(ok));
branch_i(:,1)=f;branch_i(:,2)=t;
active=m.branch(:,11)>0;
adjacency=sparse([f(active);t(active)],[t(active);f(active)],1,nb,nb);
component=conncomp(graph(adjacency));
assert(all(ismember(component(e),unique(component(k)))), ...
    'compactAC:UnanchoredInterior','An eliminated island has no retained terminal; define its de-energized/island state explicitly.');
[Y,Yf,Yt]=makeYbus(m.baseMVA,bus_i,branch_i);
L=sparse(k,(1:nk)',ones(nk,1),nb,nk);
if isempty(e)
    reciprocal_condition=1;elimination_error=0;
else
    Yee=Y(e,e);Yek=Y(e,k);reciprocal_condition=rcond(full(Yee));
    assert(isfinite(reciprocal_condition)&&reciprocal_condition>1e-12, ...
        'compactAC:SingularInterior','Eliminated network is singular or ill-conditioned; inspect islands/retention before proceeding.');
    K=-(Yee\Yek);L(e,:)=K;
    elimination_error=norm(Yee*K+Yek,inf)/max(1,norm(Yek,inf));
end
Yr=Y(k,:)*L;
lift_error=norm(Y*L-sparse(k,(1:nk)',ones(nk,1),nb,nk)*Yr,inf)/max(1,norm(Y,inf)*norm(L,inf));
assert(elimination_error<1e-10&&lift_error<1e-10,'compactAC:Algebra','Complex-admittance elimination identity failed.');
ys=zeros(nl,1);z=complex(m.branch(:,3),m.branch(:,4));
assert(all(abs(z(active))>0),'compactAC:ZeroImpedance','Active zero-impedance branch must be resolved explicitly.');
ys(active)=1./z(active);tap=m.branch(:,9);tap(tap==0)=1;tap=tap.*exp(1j*deg2rad(m.branch(:,10)));
Ys=sparse((1:nl)',f,ys./tap,nl,nb)-sparse((1:nl)',t,ys,nl,nb);
G=(Yr+Yr')/2;minimum_conductance_eigenvalue=min(real(eig(full(G))));
passive=minimum_conductance_eigenvalue>=-1e-9*max(1,norm(full(G),2));
assert(passive,'compactAC:NonPassive','Reduced network failed the Hermitian real-power dissipation screen.');
c=struct('model_kind','compact_complex_admittance_AC','model_version',1,'baseMVA',m.baseMVA, ...
    'bus',m.bus(k,:),'gen',m.gen,'retained_bus_ids',retained_ids,'anchor_bus_ids',anchor_ids, ...
    'promoted_bus_ids',extra_ids,'full_bus_ids',ids,'retained_full_rows',k,'eliminated_full_rows',e, ...
    'Yred',Yr,'voltage_lift',L,'Yfull',Y,'Yf_full',Yf,'Yt_full',Yt,'Yseries_full',Ys, ...
    'YfL',Yf*L,'YtL',Yt*L,'YseriesL',Ys*L,'detailed_mpc',m, ...
    'branch_from_bus',m.branch(:,1),'branch_to_bus',m.branch(:,2), ...
    'from_current_base_A',m.baseMVA*1000./(sqrt(3)*m.bus(f,10)), ...
    'to_current_base_A',m.baseMVA*1000./(sqrt(3)*m.bus(t,10)));
if isfield(m,'dcline'),c.dcline=m.dcline;else,c.dcline=[];end
if isfield(m,'bus_name'),c.bus_name=m.bus_name(k);end
if isfield(m,'userdata')&&isfield(m.userdata,'ac_system')
    c.branch_keys=m.userdata.ac_system.branch_keys;
    c.branch_parent_row=m.userdata.ac_system.branch_parent_row;
end
c.retention=table(ids,is_anchor,load_port,generator_port,dc_port,control_port, ...
    ismember(ids,retained_ids),m.bus(:,5),m.bus(:,6), ...
    'VariableNames',{'bus_id','anchor_148','nonzero_load','generator_terminal','DC_terminal','voltage_control', ...
    'retained','GS_MW_at_1pu','BS_MVAr_at_1pu'});
c.source_fingerprint=compact_ac_source_fingerprint(m,retained_ids);
c.validation=struct('passed',true,'anchor_bus_count',numel(anchor_ids),'retained_bus_count',nk, ...
    'promoted_necessary_bus_count',numel(extra_ids),'eliminated_bus_count',numel(e), ...
    'interior_reciprocal_condition',reciprocal_condition,'relative_interior_identity_error',elimination_error, ...
    'relative_full_lift_identity_error',lift_error,'minimum_Hermitian_conductance_eigenvalue',minimum_conductance_eigenvalue, ...
    'all_eliminated_components_connected_to_retained',true, ...
    'complex_shunts_and_phase_taps_preserved',true,'no_magnitude_threshold_pruning',true, ...
    'equivalent_edges_are_physical_conductors',false,'requires_rebuild_after_network_or_control_change',true);
c.operator_fingerprint=compact_ac_operator_fingerprint(c);
end

function [result,audit,full_result]=compact_ac_solve(c,mpopt)
%COMPACT_AC_SOLVE Newton PF on retained voltages, followed by exact recovery.
% Uses MATPOWER newtonpf/pfsoln and its dcline conversion callbacks. The Q-limit
% policy follows MATPOWER8.1 legacy runpf; no full-network Newton solve occurs.
% MATPOWER: Copyright1996-2025 PSERC/contributors, BSD3-clause.
% See ../THIRD_PARTY_NOTICES.md for the notice and license terms.
if nargin<2||isempty(mpopt)
    mpopt=mpoption('model','AC','pf.alg','NR','pf.tol',1e-10,'pf.nr.max_it',50, ...
        'pf.enforce_q_lims',0,'exp.use_legacy_core',1,'verbose',0,'out.all',0);
end
assert(strcmp(c.model_kind,'compact_complex_admittance_AC')&&c.validation.passed);
assert(strcmpi(mpopt.model,'AC')&&strcmpi(mpopt.pf.alg,'NR') ...
    &&mpopt.pf.current_balance==0&&mpopt.pf.v_cartesian==0, ...
    'compactAC:SolverOptions','This solver implements AC power/polar Newton PF.');
assert(ismember(mpopt.pf.enforce_q_lims,[0 1 2]));
assert(strcmp(c.source_fingerprint,compact_ac_source_fingerprint(c.detailed_mpc,c.retained_bus_ids)), ...
    'compactAC:StaleNetwork','Detailed data changed. Rebuild with compact_ac_build before solving.');
assert(strcmp(c.operator_fingerprint,compact_ac_operator_fingerprint(c)), ...
    'compactAC:EditedOperator','Reduction or recovery data changed. Rebuild with compact_ac_build before solving.');
m=c.detailed_mpc;
assert(isequal(c.bus,m.bus(c.retained_full_rows,:))&&isequal(c.gen,m.gen), ...
    'compactAC:EditedView','Edit the detailed input and rebuild; compact bus/gen fields are immutable views.');
if isfield(m,'dcline'),assert(isequal(c.dcline,m.dcline),'compactAC:EditedView','Rebuild after converter edits.');end
if size(m.branch,2)<17,m.branch(:,17)=0;end
mi=ext2int(m,mpopt);bus=mi.bus;gen=mi.gen;branch=mi.branch;nb=size(bus,1);nk=numel(c.retained_bus_ids);
[ok,full_rows]=ismember(mi.order.bus.i2e,c.full_bus_ids);assert(all(ok)&&nb==numel(c.full_bus_ids));
[ok,k]=ismember(c.retained_bus_ids,mi.order.bus.i2e);assert(all(ok));
[ok,gen_k]=ismember(gen(:,1),k);assert(all(ok),'compactAC:ControlPort','A converted generator/converter lies outside retained buses.');
Y=c.Yfull(full_rows,full_rows);L=c.voltage_lift(full_rows,:);
br_rows=mi.order.branch.status.on;Yf=c.Yf_full(br_rows,full_rows);Yt=c.Yt_full(br_rows,full_rows);
[ref,pv,pq]=bustypes(bus,gen);assert(all(ismember([ref;pv],k)));
on=find(gen(:,8)>0);gbus=gen(on,1);
V0=bus(:,8).*exp(1j*pi/180*bus(:,9));vcb=ones(nb,1);vcb(pq)=0;
vg_rows=find(vcb(gbus));
% Preserve MATPOWER's exact generator order, including last dcline VG at a shared bus.
V0(gbus(vg_rows))=gen(on(vg_rows),6)./abs(V0(gbus(vg_rows))).*V0(gbus(vg_rows));
Vk=V0(k);ref0=ref;reference_angle0=bus(ref0,9);qlim=mpopt.pf.enforce_q_lims;
iterations=0;outer=0;limited=[];trace=struct([]);t0=tic;
initial_control=struct('bus_type',bus(:,2),'generator_bus',gen(:,1), ...
    'generator_PG',gen(:,2),'generator_QG',gen(:,3),'generator_VG',gen(:,6), ...
    'full_internal_bus_ids',mi.order.bus.i2e,'retained_initial_voltage',Vk, ...
    'converted_generator_count',size(gen,1),'reference_bus_ids',mi.order.bus.i2e(ref));
while true
    outer=outer+1;assert(outer<=2*size(gen,1)+1,'compactAC:QControlLoop','Reactive-control loop exceeded finite switching bound.');
    bc=bus(k,:);bc(:,1)=(1:nk)';gc=gen;gc(:,1)=gen_k;
    [rc,pc,qc]=bustypes(bc,gc);
    assert(isequal(k(rc),ref)&&isequal(sort(k(pc)),sort(pv)));
    Sbus=@(Vm)makeSbus(mi.baseMVA,bc,gc,mpopt,Vm);
    [Vk,success,it]=newtonpf(c.Yred,Sbus,Vk,rc,pc,qc,mpopt);
    V=L*Vk;
    [bus,gen,branch]=pfsoln(mi.baseMVA,bus,gen,branch,Y,Yf,Yt,V,ref,pv,pq,mpopt);
    iterations=iterations+it;
    mx=find(gen(:,8)>0&gen(:,3)>gen(:,4)+mpopt.opf.violation);
    mn=find(gen(:,8)>0&gen(:,3)<gen(:,5)-mpopt.opf.violation);
    trace=[trace struct('outer_iteration',outer,'NR_iterations',it,'NR_converged',logical(success), ...
        'upper_Q_violations',numel(mx),'lower_Q_violations',numel(mn),'retained_buses',nk, ...
        'Newton_unknowns',numel(pc)+2*numel(qc))]; %#ok<AGROW>
    if ~success||~qlim||isempty([mx;mn]),break;end
    infeas=union(mx,mn);remaining=find(gen(:,8)>0&ismember(bus(gen(:,1),2),[2 3]));
    if isequal(infeas,remaining)&&(isempty(mx)||isempty(mn)),success=false;break;end
    if qlim==2
        [~,largest]=max([gen(mx,3)-gen(mx,4);gen(mn,5)-gen(mn,3)]);
        if largest>numel(mx),mn=mn(largest-numel(mx));mx=[];else,mx=mx(largest);mn=[];end
    end
    gen(mx,3)=gen(mx,4);gen(mn,3)=gen(mn,5);hit=[mx;mn];
    assert(numel(ref)==1||~any(bus(gen(hit,1),2)==3), ...
        'compactAC:MultipleReferences','Q-limit switching of multiple reference buses is unsupported.');
    bus(gen(hit,1),2)=1;oldref=ref;[ref,pv,pq]=bustypes(bus,gen);
    if ~isequal(ref,oldref),bus(ref,2)=3;bus(pv,2)=2;end
    limited=[limited;hit]; %#ok<AGROW>
end
if qlim&&~isempty(limited)&&~isequal(ref,ref0)
    assert(isscalar(ref0));bus(:,9)=bus(:,9)-bus(ref0,9)+reference_angle0;
end
mi.bus=bus;mi.gen=gen;mi.branch=branch;mi.success=logical(success);mi.iterations=iterations;mi.et=toc(t0);
full_result=int2ext(mi);
if ~isempty(full_result.order.gen.status.off),full_result.gen(full_result.order.gen.status.off,[2 3])=0;end
if ~isempty(full_result.order.branch.status.off),full_result.branch(full_result.order.branch.status.off,14:17)=0;end
Vfull=full_result.bus(:,8).*exp(1j*deg2rad(full_result.bus(:,9)));Vk=Vfull(c.retained_full_rows);
currents=[abs(c.YfL*Vk).*c.from_current_base_A,abs(c.YtL*Vk).*c.to_current_base_A, ...
    abs(c.YseriesL*Vk).*c.to_current_base_A];
root=fileparts(fileparts(fileparts(fileparts(mfilename('fullpath')))));
addpath(fullfile(root,'scripts','nygrid_2025_acpf_profile_audit','acpf'));
addpath(fullfile(root,'scripts','nygrid_2025_ac_system','thermal'));
[audit,detail]=audit_profile_pf(c.detailed_mpc,full_result);
audit.PF_backend='MATPOWER_newtonpf_compact_complex_admittance';audit.pf_enforce_q_lims=qlim;
audit.compact_retained_bus_count=nk;audit.eliminated_bus_count=numel(c.eliminated_full_rows);
audit.no_full_network_Newton_solve=true;audit.reactive_control_outer_iterations=outer;
audit.recovery_voltage_identity_error_pu=max(abs(Vfull-c.voltage_lift*Vk));
audit.recovered_current_operator_crosscheck_A=max(abs(currents-[detail.from_terminal_current_amp, ...
    detail.to_terminal_current_amp,detail.series_current_amp]),[],'all');
audit.eliminated_current_residual_pu=max([0;abs(c.Yfull(c.eliminated_full_rows,:)*Vfull)]);
audit.reduction_and_equation_gate=audit.AC_equation_gate&&c.validation.passed ...
    &&audit.recovery_voltage_identity_error_pu<1e-8&&audit.recovered_current_operator_crosscheck_A<1e-5;
audit.reduction_does_not_repair_operating_or_asset_assumptions=true;
full_result.userdata.compact_ac=struct('solved_bus_count',nk,'full_Newton_solve_used',false, ...
    'source_fingerprint',c.source_fingerprint,'retained_bus_ids',c.retained_bus_ids);
result=struct('model_kind',c.model_kind,'baseMVA',c.baseMVA,'bus',full_result.bus(c.retained_full_rows,:), ...
    'gen',full_result.gen,'dcline',full_result.dcline,'success',logical(success),'iterations',iterations,'et',mi.et, ...
    'retained_bus_ids',c.retained_bus_ids,'recovered_full_voltage',Vfull, ...
    'recovered_line_current_A',currents,'line_current_columns',{{'from_terminal_A','to_terminal_A','series_A'}}, ...
    'source_fingerprint',c.source_fingerprint,'control_trace',trace,'initial_control',initial_control);
if isfield(c,'bus_name'),result.bus_name=c.bus_name;end
end

function digest=compact_ac_source_fingerprint(m,retained_ids)
% Numerical source contract, independent of labels and transient timing data.
engine=java.security.MessageDigest.getInstance('SHA-256');
parts={double(m.baseMVA),double(m.bus),double(m.gen),double(m.branch(:,1:13)),double(retained_ids(:))};
if isfield(m,'dcline'),parts{end+1}=double(m.dcline);end
for k=1:numel(parts)
    a=parts{k};shape=double(size(a));
    engine.update(typecast(shape(:),'int8'));
    if ~isempty(a),engine.update(typecast(a(:),'int8'));end
end
raw=typecast(engine.digest(),'uint8');digest=lower(reshape(dec2hex(raw,2)',1,[]));
end

function digest=compact_ac_operator_fingerprint(c)
%COMPACT_AC_OPERATOR_FINGERPRINT Bind the immutable reduction/recovery cache.
% Hash sparse coordinates as well as real and imaginary values. Metadata that
% labels recovered conductors is protected alongside the Newton operators.
engine=java.security.MessageDigest.getInstance('SHA-256');
fields={'Yred','voltage_lift','Yfull','Yf_full','Yt_full','Yseries_full', ...
    'YfL','YtL','YseriesL','retained_bus_ids','anchor_bus_ids','promoted_bus_ids', ...
    'full_bus_ids','retained_full_rows','eliminated_full_rows', ...
    'from_current_base_A','to_current_base_A','branch_from_bus','branch_to_bus'};
if isfield(c,'branch_parent_row'),fields{end+1}='branch_parent_row';end
for n=1:numel(fields)
    engine.update(int8(fields{n}));
    a=double(c.(fields{n}));shape=double(size(a));
    engine.update(typecast(shape(:),'int8'));
    if issparse(a)
        [i,j,v]=find(a);parts={double(1),double(i),double(j),real(v),imag(v)};
    else
        parts={double(0),real(a(:)),imag(a(:))};
    end
    for q=1:numel(parts)
        if ~isempty(parts{q}),engine.update(typecast(parts{q}(:),'int8'));end
    end
end
labels={c.source_fingerprint};
if isfield(c,'branch_keys'),labels=[labels;cellstr(string(c.branch_keys(:)))];end
for n=1:numel(labels)
    bytes=unicode2native(labels{n},'UTF-8');count=double(numel(bytes));
    engine.update(typecast(count,'int8'));engine.update(typecast(bytes(:),'int8'));
end
raw=typecast(engine.digest(),'uint8');digest=lower(reshape(dec2hex(raw,2)',1,[]));
end
